mapper.select:
select t.device_code, (case when length(IFNULL(rel.device_name, '')) = 0 then t.device_name else rel.device_name end ) name, t.address location, ST_Distance_Sphere( ST_GeomFromText(CONCAT('POINT(',#{param.longitude},' ',#{param.latitude},')')), ST_GeomFromText(CONCAT('POINT(',t.longitude,' ',t.latitude,')')) ) as distance, t.model_code deviceModelCode, t.manufacturer_code modelCode, t.longitude, t.latitude, t.altitude, t.resource_status deviceStatus, t.location_code access_node from vm_order_uav_nest_devices o inner join vm_uav_nest_device_info t on t.device_code = o.device_code LEFT JOIN vm_tenant_device_common_rel_t rel ON rel.device_code = o.device_code and rel.tenant_id = o.tenant_id and rel.industry_code = o.industry_code and rel.delete_flag = 0 and rel.device_type = 4 where o.delete_flag = '0' and t.delete_flag = '0' and o.ord_status in (0,1,2)
and ST_Distance_Sphere( ST_GeomFromText(CONCAT('POINT(',#{param.longitude},' ',#{param.latitude},')')), ST_GeomFromText(CONCAT('POINT(',t.longitude,' ',t.latitude,')')) ) <= #{param.radius}
and t.device_code != #{param.notIncludeDeviceCode}
${param.dataScope} group by t.device_code order by t.id
limit #{param.limitSize}

SELECT DISTINCT m.device_code as deviceCode, m.resource_status, m.location_code access_node, m.device_name, m.province_code as provinceId,pro.area_name as provinceName, m.city_code as cityId, city.area_name as cityName,m.county_code as countyId,county.area_name as countyName, m.town_code as townCode, town.area_name as townName, m.site_id siteCode, m.longitude,m.latitude, 'false' AS checked, '1' AS proLevel, 'true' isNestDevice, '2' AS cityLevel,'3' AS countryLevel,'4' AS devLevel, m.model_code deviceModelCode, m.altitude, m.position_fix uavNestPositionFix, m.calibration_status uavNestCalibrationStatus, (case when length(IFNULL(rel.device_name, '')) = 0 then m.device_name else rel.device_name end ) deviceAlias FROM vm_order_uav_nest_devices ord LEFT JOIN vm_uav_nest_device_info m on m.device_code = ord.device_code LEFT JOIN sys_area pro on pro.area_code = m.province_code LEFT JOIN sys_area city on city.area_code = m.city_code LEFT JOIN sys_area county on county.area_code = m.county_code LEFT JOIN sys_area town on town.area_code = m.town_code LEFT JOIN vm_tenant_device_common_rel_t rel ON rel.device_code = m.device_code and rel.tenant_id = ord.tenant_id and rel.industry_code = ord.industry_code and rel.delete_flag = '0' and rel.device_type = 4 WHERE m.delete_flag= '0' and ord.ord_status in (0, 1, 2) and ord.delete_flag= '0'
and ord.industry_code = #{param.industryCode}
and ord.tenant_id = #{param.tenantId}
and m.resource_status != 2
and m.device_type in
#{type}
and m.resource_status in
#{item}
${param.dataScope} ORDER BY m.province_code, m.city_code, m.county_code, m.town_code, m.device_code

SELECT DISTINCT m.device_code as deviceCode, m.resource_status deviceStatus, m.location_code access_node, m.device_name, m.province_code as provinceId,pro.area_name as provinceName, m.city_code as cityId, city.area_name as cityName,m.county_code as countyId,county.area_name as countyName, m.town_code as townCode, town.area_name as townName, m.site_id siteCode, m.longitude,m.latitude, 'false' AS checked, '1' AS proLevel, m.altitude, m.model_code deviceModelCode, case when IFNULL(dct.user_device_coll_id,0) = 0 then '0' else '1' end isMonitor, 'true' isNestDevice, '2' AS cityLevel,'3' AS countryLevel,'4' AS devLevel, m.position_fix uavNestPositionFix, m.calibration_status uavNestCalibrationStatus, (case when length(IFNULL(rel.device_name, '')) = 0 then m.device_name else rel.device_name end ) deviceAlias FROM vm_order_uav_nest_devices ord LEFT JOIN vm_uav_nest_device_info m on m.device_code = ord.device_code LEFT JOIN sys_area pro on pro.area_code = m.province_code LEFT JOIN sys_area city on city.area_code = m.city_code LEFT JOIN sys_area county on county.area_code = m.county_code LEFT JOIN sys_area town on town.area_code = m.town_code LEFT JOIN vm_tenant_device_common_rel_t rel ON rel.device_code = m.device_code and rel.tenant_id = ord.tenant_id and rel.industry_code = ord.industry_code and rel.delete_flag = '0' and rel.device_type = 4 LEFT JOIN vm_user_device_collection_t dct ON dct.coll_obj_code = m.device_code AND dct.coll_obj_type = '15' AND dct.user_id = #{param.userId} WHERE m.delete_flag= '0' and ord.ord_status in (0, 1, 2) and ord.delete_flag= '0'
and ord.industry_code = #{param.industryCode}
and ord.tenant_id = #{param.tenantId}
and m.resource_status != 2
and dct.user_device_coll_id IS NOT NULL
and m.device_type in
#{type}
and m.resource_status in
#{item}
and m.device_code not in
#{item}
${param.dataScope} ORDER BY m.province_code, m.city_code, m.county_code, m.town_code, m.device_code

SELECT distinct dev.device_code,
(case when length(IFNULL(rel.device_name, '')) = 0 then dev.device_name else rel.device_name end) as device_name,
dev.resource_status as status,'true' isNestDevice,
dev.position_fix uavNestPositionFix,
dev.calibration_status uavNestCalibrationStatus,
dev.address location, dev.latitude, dev.longitude, dev.site_id siteCode
FROM vm_uav_nest_device_info dev
left join vm_order_uav_nest_devices t1 on dev.device_code = t1.device_code
left join vm_tenant_device_common_rel_t rel ON rel.device_code = t1.device_code
and rel.tenant_id = t1.tenant_id and rel.industry_code = t1.industry_code
and rel.delete_flag = '0' and rel.device_type = 4
where t1.delete_flag = '0' and dev.delete_flag = '0' and t1.ord_status in (0,1,2)

    AND dev.site_id = #{param.siteCode}


    AND dev.latitude = #{param.latitude}


    AND dev.longitude = #{param.longitude}


    AND dev.city_code = #{param.cityId}


    and dev.device_code not in

        #{item}


${param.dataScope}
order by dev.resource_status, dev.device_code

SELECT DISTINCT gg.dept_id as org_id, gg.dept_name as org_name, gg.dept_level as org_level, gg.parent_id as parent_org_id, dd.device_code, IFNULL(rel.device_name, de.device_name) AS device_name, concat(gg.dept_level + 1) AS devLevel, 'false' AS checked, de.longitude, de.latitude, 1 AS num, de.site_id site_code,de.resource_status device_status, case when IFNULL(dct.user_device_coll_id, 0) = 0 then '0' else '1' end isMonitor,'true' isNestDevice, de.position_fix uavNestPositionFix, de.calibration_status uavNestCalibrationStatus FROM sys_dept gg LEFT JOIN vm_organ_device_rel_t dd ON gg.dept_id = dd.dept_id and dd.device_type = 15 and gg.industry_code = dd.industry_code LEFT JOIN vm_uav_nest_device_info de ON dd.device_code = de.device_code LEFT JOIN vm_user_device_collection_t dct ON dct.coll_obj_code = de.device_code AND dct.coll_obj_type = '15' and dct.user_id = #{param.userId} left join vm_order_uav_nest_devices vod on vod.industry_code = dd.industry_code and vod.device_code = de.device_code and vod.tenant_id = gg.tenant_id LEFT JOIN vm_tenant_device_common_rel_t rel ON rel.device_code = vod.device_code and rel.tenant_id = vod.tenant_id and rel.industry_code = vod.industry_code and rel.delete_flag = '0' and rel.device_type = 4 WHERE gg.del_flag = '0' AND dd.delete_flag = '0' AND de.delete_flag = '0' AND dd.device_code IS NOT NULL AND dd.device_code != '' AND vod.delete_flag = '0' AND vod.ord_status in (0,1,2)
and dct.user_device_coll_id IS NOT NULL
and de.resource_status != 2
and de.resource_status = #{param.deviceStatus}
and de.resource_status in
#{item}
and de.device_code not in
#{item}
${param.dataScope} ORDER BY gg.dept_id,dd.device_code

SELECT distinct dev.device_code, (case when length(IFNULL(tdr.device_name, '')) = 0 then dev.device_name else tdr.device_name end ) as device_name, dev.resource_status device_status, 'true' isNestDevice, dev.position_fix uavNestPositionFix, dev.calibration_status uavNestCalibrationStatus, ifnull(dev.hanging_height, 0) as height, dev.latitude, dev.longitude, dev.site_id site_code FROM vm_uav_nest_device_info dev left join vm_order_uav_nest_devices t1 on dev.device_code = t1.device_code left join vm_tenant_device_common_rel_t tdr on tdr.device_code = t1.device_code and tdr.tenant_id = t1.tenant_id and tdr.industry_code = t1.industry_code and tdr.delete_flag = 0 and tdr.device_type = 4 where dev.delete_flag = '0' AND t1.delete_flag = '0' AND t1.ord_status IN ( 0, 1, 2 )
AND dev.province_code = #{param.provinceId}
AND dev.city_code = #{param.cityId}
AND dev.county_code = #{param.countyId}
AND dev.town_code = #{param.townCode}
and dev.device_code not in
#{item}
${param.dataScope}
